// --- Section 1/48/54: mission headline regression -------------------------
// "what events should i do" was the exact reported bug: Coach answered
// "I'm not totally sure what you mean" for a plainly understandable
// EVENT_RECOMMENDATION request. Locked in explicitly, plus the
// capitalization-invariance requirement (section 48).
describe('batch3 regression: EVENT_RECOMMENDATION headline case', () => {
    it('"what events should i do" is recognized as EVENT_RECOMMENDATION, never UNKNOWN', () => {
        const res = ask('what events should i do');
        expect(res.text).not.toMatch(UNKNOWN_RE);
        expect(res.intent).toBe('clarify.recommend');
    });
    it('"What events should I do?" behaves identically regardless of capitalization', () => {
        const res = ask('What events should I do?');
        expect(res.text).not.toMatch(UNKNOWN_RE);
        expect(res.intent).toBe('clarify.recommend');
    });
    it.each(['what events should i do', 'what event should i do', 'what should i compete in', 'what should i pick', 'which event is good for me', 'what do you recommend', 'what competition should i choose'])('paraphrase "%s" routes to the same EVENT_RECOMMENDATION intent', (phrase) => {
        const res = ask(phrase);
        expect(res.text).not.toMatch(UNKNOWN_RE);
        expect(res.intent).toBe('clarify.recommend');
    });
});

// --- Section 54: required regression cases ---------------------------------
describe('batch3 required regression cases', () => {
    it('"can you help me" -> HELP', () => {
        const res = ask('can you help me');
        expect(res.text).not.toMatch(UNKNOWN_RE);
    });
    it('"help" -> HELP', () => {
        const res = ask('help');
        expect(res.text).not.toMatch(UNKNOWN_RE);
    });
    it('"i have a question about webmaster" -> QUESTION_OPENING + Webmaster context', () => {
        const res = ask('i have a question about webmaster');
        expect(res.intent).toBe('question.opening');
    });
    it('"im doing webmaster" -> EVENT_CONTEXT + Webmaster', () => {
        const res = ask('im doing webmaster');
        expect(res.intent).toBe('context.acknowledge');
    });
    it('"how many ppl can do webmaster" -> TEAM_SIZE + Webmaster', () => {
        const res = ask('how many ppl can do webmaster');
        expect(res.intent).toBe('team.general');
        expect(res.text).toMatch(/\d/);
    });
    it('"what careers connect to this" -> CAREERS using the active event, not a different one', () => {
        const turns = askChain(['im doing webmaster', 'what careers connect to this']);
        const last = turns.at(-1);
        expect(last.text).not.toMatch(UNKNOWN_RE);
        expect(last.text).not.toMatch(/career prep/i);
    });
    it('"what do i wear for nationals" -> DRESS_CODE / NATIONAL_CONFERENCE', () => {
        const res = ask('what do i wear for nationals');
        expect(res.text).not.toMatch(UNKNOWN_RE);
    });
    it('"what materials do i need" -> MATERIALS using active event context', () => {
        const turns = askChain(['im doing webmaster', 'what materials do i need']);
        const last = turns.at(-1);
        expect(last.text).not.toMatch(UNKNOWN_RE);
    });
    it('"what do i submit" -> SUBMISSIONS using active event context', () => {
        const turns = askChain(['im doing webmaster', 'what do i submit']);
        const last = turns.at(-1);
        expect(last.text).not.toMatch(UNKNOWN_RE);
    });
    it('"whats this years theme" -> THEME using active event context', () => {
        const turns = askChain(['im doing webmaster', 'whats this years theme']);
        const last = turns.at(-1);
        expect(last.text).not.toMatch(UNKNOWN_RE);
    });
    it('"can i use chatgpt" -> AI_USAGE, not "are you an AI"', () => {
        const res = ask('can i use chatgpt');
        expect(res.text).not.toMatch(UNKNOWN_RE);
        expect(res.text).not.toMatch(/rule-based assistant/i);
    });
    it('"where did you get that" -> SOURCE_REQUEST', () => {
        const res = ask('where did you get that');
        expect(res.text).not.toMatch(UNKNOWN_RE);
    });
    it('"can you text tsa" -> CAPABILITY_LIMIT', () => {
        const res = ask('can you text tsa');
        expect(res.text).not.toMatch(UNKNOWN_RE);
    });
    it('"bro thats not what i asked" -> CONVERSATION_REPAIR, not counted as a misunderstanding', () => {
        const res = ask('bro thats not what i asked');
        expect(['unknown', 'tsa-unsupported']).not.toContain(res.kind);
    });
});

// --- Section 44: collision tests --------------------------------------------
// Large vocabulary expansion risks generic words silently hijacking a
// different, more specific event/entity. Confirm the guardrails hold.
describe('batch3 collision tests', () => {
    it('"career" does not select Career Prep when a different event is active', () => {
        const turns = askChain(['im doing robotics', 'high school', 'what careers connect to this']);
        const last = turns.at(-1);
        expect(last.text).not.toMatch(/career prep/i);
    });
    it('"software" does not silently switch the active event away from Webmaster', () => {
        const turns = askChain(['im doing webmaster', 'what software do i need']);
        const last = turns.at(-1);
        expect(last.text).not.toMatch(UNKNOWN_RE);
    });
    it('generic "materials"/"cost"/"rules"/"theme"/"difficulty"/"deadline" words do not change the active event entity', () => {
        const turns = askChain(['im doing webmaster', 'what materials do i need', 'how much does it cost', 'what are the rules', 'whats the theme', 'how hard is it', 'whats the deadline']);
        for (const t of turns) expect(t.text).not.toMatch(UNKNOWN_RE);
    });
    it('an unrelated "what shoes should I buy" is not hijacked into a dress-code answer', () => {
        const res = ask('what shoes should i buy for running');
        expect(res.text).not.toMatch(/dress code/i);
    });
});

// --- Section 40/49: EVENT_RECOMMENDATION with no prior context -------------
describe('batch3: EVENT_RECOMMENDATION response quality', () => {
    it('does not claim not to understand, and does not silently pick an event', () => {
        const res = ask('what should i compete in');
        expect(res.text).not.toMatch(UNKNOWN_RE);
        // Should invite preference info, not assert a specific event as fact.
        expect(res.text.toLowerCase()).toMatch(/enjoy|like|interest|prefer|recommend/);
    });
});

// --- Section 29/54: short answers to a REAL preceding Coach question -------
// Division-only replies ("middle school", "high school i think") resolve
// against a genuine Coach-initiated clarification: a division-ambiguous
// event name triggers "Are you asking about the High School or Middle
// School version?", and the bare reply completes it. This is the one
// short-answer flow that actually exists in the product today — the
// remaining SHORT_ANSWER_CONTEXTUAL phrases (grade level, state name,
// "still deciding"/"not sure yet") describe answers a REAL preceding Coach
// question would resolve, but Coach has no dedicated grade/state-asking
// flow to attach them to; inventing one is out of this milestone's scope
// (natural-language understanding only, no new product capability), so
// they remain in the corpus as vocabulary data without a standalone or
// chained behavioral assertion.
describe('batch3 context chains: short division answers resolve a real Coach clarification', () => {
    const divisionChains = [
        ['im doing robotics', 'middle school'],
        ['im doing robotics', 'high school i think'],
        ['im doing coding', 'middle school'],
        ['im doing coding', 'high school i think'],
    ];
    it.each(divisionChains)('after "%s", the reply "%s" resolves the division clarification', (opener, answer) => {
        const turns = askChain([opener, answer]);
        const last = turns.at(-1);
        expect(last.text, `"${answer}" after "${opener}" fell back to unknown: "${last.text}"`).not.toMatch(UNKNOWN_RE);
    });
});

// --- Methodology note -------------------------------------------------------
// Candidates were generated combinatorially: the full 83-row TSA Hub event
// dataset crossed with question templates (EVENT_INFO/TEAM_SIZE/RULES/
// PREPARATION/CAREERS/MATERIALS/SUBMISSIONS/COST/DIFFICULTY), preference
// words crossed with EVENT_RECOMMENDATION templates, event-name pairs
// crossed with EVENT_COMPARISON templates, and hand-authored long-form
// paragraphs plus template-generated long-form paragraphs for the
// LONG_UTTERANCE group. 3527 raw candidates were generated, 146 were exact
// duplicates of Batch 1/2 phrases (removed), 16 were internal duplicates
// (removed), leaving 3365 net new. A full engine sweep against all 3365
// found real NLU gaps (grouped by root cause, not per-phrase): the mission's
// headline EVENT_RECOMMENDATION bug ("what events should i do" never
// matched because every existing pattern required "pick"/"choose"/
// "recommend" specifically), a pre-existing bug where the bare word
// "chatgpt"/"gpt" anywhere in a message got hijacked into "are you an AI?"
// instead of answering the real AI-usage-policy question, missing synonym
// mappings for named AI tools (chatgpt/copilot/claude/gemini/midjourney ->
// "ai") that broke rule-data retrieval, and roughly two dozen narrower
// regex gaps across RULES/MATERIALS/SUBMISSIONS/COST/DIFFICULTY/THEME/
// CAREERS/DRESS_CODE/DEADLINES/CAPABILITY_LIMIT/GENERAL_HELP/FRUSTRATION/
// CORRECTION/TEAM_SIZE. All were fixed as generalized regex/normalization
// changes (never per-phrase branches). Final full-corpus unknown rate after
